import * as React from "react"

function DisabledButtonActiveButton({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="disabled-button-active-button"
      className={className}
      {...props}
    >
      <div className="flex gap-2">

        <button className="bg-gray-300 px-4 py-2 rounded-md cursor-not-allowed opacity-50" disabled>
          Disabled Button
        </button>


        <button className="bg-green-500 hover700 active800 px-4 py-2 rounded-md text-white">
          Active Button
        </button>

      </div>
    </div>
  )
}

export { DisabledButtonActiveButton }
